def solve(grid):
    if not grid:
        return []

    n = len(grid)
    # Create a 3n x 3n grid initialized with zeros
    result = [[0 for _ in range(3 * n)] for _ in range(3 * n)]

    # Iterate through the input grid
    for i in range(n):
        for j in range(n):
            # If the cell contains 2, copy the entire input grid 
            # to the corresponding 3x3 block in the output
            if grid[i][j] == 2:
                for r in range(n):
                    for c in range(n):
                        result[3 * i + r][3 * j + c] = grid[r][c]

    return result
